import java.io.Serializable;

public class Persona implements Serializable {

    private static final long serialVersionUID = 284796237982514963L;

    private String nombre;
    private int edad;

    public Persona(String nombre, int edad) {
        this.nombre = nombre;
        this.edad = edad;
    }

    public String getNombre() {
        return nombre;
    }

    public void setNombre(String nombre) {
        this.nombre = nombre;
    }

    public int getEdad() {
        return edad;
    }

    public void setEdad(int edad) {
        this.edad = edad;
    }

}

String rutaFichero = "C:\\documentos\\Persona.bin";

// Escritura
FileOutputStream fos = new FileOutputStream(rutaFichero);
ObjectOutputStream oos = new ObjectOutputStream(fos);
Persona persona = new Persona("Pepe", 25);
oos.writeObject(persona);
oos.close();

// Lectura
FileInputStream fis = new FileInputStream(rutaFichero);
ObjectInputStream ois = new ObjectInputStream(fis);
Persona objeto = (Persona) ois.readObject();
System.out.println("Nombre: " + objeto.getNombre() + " Edad: " + objeto.getEdad());
ois.close();
